        for i in range(N):
            temp = input()
            sum = 0
            nokai = []
            for index, e in enumerate(temp):
                if e == 'o':
                    sum += A[index]
                else:
                    nokai.append(A[index])
            sort_nokai = sorted(nokai, reverse=True)
            nolist.append(sort_nokai)
