def solve(text):
    def program():
        def solve(h, w, m, t, a, x):
            a = [_ - 1 for _ in a]
            cnt = {color: 0 for color in x}
            S_row = set()
            S_col = set()
            for k in range(m - 1, -1, -1):
                if t[k] == 1:
                    if a[k] not in S_row:
                        S_row.add(a[k])
                        cnt[x[k]] += w - len(S_col)
                elif a[k] not in S_col:
                    S_col.add(a[k])
                    cnt[x[k]] += h - len(S_row)
