import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        A, M, L, R = map(int, input().split())
        x1 = (L - A + M - 1) // M  # Corrected ceiling division
        x2 = (R - A) // M
        if (L - A) % M == 0:
            print(abs(x1 - x2) + 1)
        else:
            print(abs(x1 - x2))
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()

